import json
from datetime import datetime, timedelta

JSON_PATH = "repair-sessions.json"
JSONL_PATH = "repair-dataset.jsonl"

NEW = [
# ---- Windows Internals ----
("internals","LSASS.exe crashes and the machine force-reboots with a 60-second countdown",
 "LSASS is a protected critical process; when it crashes Windows forces a reboot. The Application-log crash record blames a third-party authentication DLL injected into LSASS (a smartcard middleware), not lsass.exe itself.",
 [("Get-WinEvent -FilterHashtable @{LogName='Application'; Id=1000} -MaxEvents 2 | Select-Object -ExpandProperty Message","Faulting application: lsass.exe, faulting module: scmiddleware.dll","")],
 "Update or remove the middleware owning the faulting DLL; consider enabling LSASS protection (RunAsPPL) afterward, which blocks unsigned DLLs from loading into LSASS entirely."),
("internals","Desktop Window Manager (dwm.exe) crashes repeatedly, screen flashes black every few minutes",
 "DWM crashes almost always trace to the graphics driver; each dwm.exe crash record here references the display driver's user-mode DLL, and the crashes started right after a GPU driver update.",
 [("Get-WinEvent -FilterHashtable @{LogName='Application'; Id=1000} -MaxEvents 3 | Select-Object -ExpandProperty Message","Faulting application: dwm.exe, faulting module: nvwgf2umx.dll (all 3 events)","")],
 "Roll back or clean-reinstall the GPU driver (DDU in Safe Mode, then the latest stable release); dwm.exe crashes referencing a vendor graphics DLL are driver bugs, not Windows corruption."),
("internals","Winlogon reports failures and logons intermittently hang at a black screen before the desktop",
 "Winlogon's notification subscribers run at logon, and a third-party credential provider registered by remote-access software is timing out, delaying the handoff to the shell -- Winlogon itself is healthy.",
 [("Get-WinEvent -FilterHashtable @{LogName='Application'; ProviderName='Microsoft-Windows-Winlogon'} -MaxEvents 4 | Select-Object Id, Message","Notification subscriber <ThirdPartyCP> took 118 seconds to handle the event (Logon)","")],
 "Update or uninstall the software owning the slow credential provider/notification subscriber named in the event; logons return to normal speed once the hanging subscriber is gone."),
("internals","RuntimeBroker.exe consumes high CPU constantly, not just briefly",
 "RuntimeBroker brokers permissions for Store/UWP apps and should idle near zero; sustained high CPU correlates with one specific UWP app continuously polling location/notifications in a tight loop -- the broker is the messenger, not the culprit.",
 [("Get-Process RuntimeBroker | Select-Object CPU, Id","CPU     Id\n---     --\n1240.5 6120","")],
 "Identify the misbehaving UWP app (close Store apps one at a time and watch RuntimeBroker's CPU), then update/reinstall that app or disable its background access under Settings > Apps > Installed apps > Advanced options."),
("internals","Windows Search database is corrupted -- searches return nothing and SearchIndexer errors fill the log",
 "The search index database (Windows.edb) failed ESENT recovery after an unclean shutdown; the indexer keeps trying to open the damaged database, logging errors and returning empty results instead of rebuilding automatically.",
 [("Get-WinEvent -FilterHashtable @{LogName='Application'; ProviderName='ESENT'} -MaxEvents 3 | Select-Object -ExpandProperty Message","Database recovery failed for C:\\ProgramData\\Microsoft\\Search\\Data\\Applications\\Windows\\Windows.edb (-1216)","")],
 "Stop WSearch, delete the contents of 'C:\\ProgramData\\Microsoft\\Search\\Data', restart WSearch -- the index rebuilds from scratch (may take hours to complete on large drives, but searches start improving immediately)."),
("internals","StartMenuExperienceHost crashes on every Start button press -- menu flashes open then vanishes",
 "The Start menu host app's local state database is corrupted, so it crashes during startup each time it's launched; Windows relaunches it on the next click, producing the flash-then-vanish loop.",
 [("Get-WinEvent -FilterHashtable @{LogName='Application'; Id=1000} -MaxEvents 3 | Select-Object -ExpandProperty Message","Faulting application: StartMenuExperienceHost.exe (3 times in 5 minutes)","")],
 "Re-register the Start menu package from an elevated PowerShell: 'Get-AppxPackage Microsoft.Windows.StartMenuExperienceHost | Reset-AppxPackage'; if unavailable on this build, delete '%LocalAppData%\\Packages\\Microsoft.Windows.StartMenuExperienceHost_cw5n1h2txyewy\\TempState' and restart."),
("internals","COM registration for a core component broke -- multiple apps fail with 'Class not registered' (0x80040154)",
 "0x80040154 means the requested COM class's registration is missing from the registry; here a cleanup utility removed HKCR CLSID entries belonging to a shared Microsoft component that several apps depend on.",
 [("Get-ItemProperty 'HKLM:\\SOFTWARE\\Classes\\CLSID\\{F5078F32-C551-11D3-89B9-0000F81FE221}\\InprocServer32' -ErrorAction SilentlyContinue","(key missing -- msxml3.dll class unregistered)","")],
 "Re-register the component ('regsvr32 msxml3.dll' for this CLSID); for broader damage run 'sfc /scannow' which restores default COM registrations for protected components, and stop using aggressive registry cleaners."),
("internals","Registry hive transaction logs (.LOG1/.LOG2) are huge and a hive won't load cleanly after power loss",
 "The hive's transaction logs contain unreplayed writes from the power loss; Windows normally replays them at mount, but a size/sequence mismatch is blocking recovery, leaving the hive mounted from an older consistent state.",
 [("Get-ChildItem 'C:\\Windows\\System32\\config' -Filter 'SOFTWARE*' | Select-Object Name, Length","Name          Length\n----          ------\nSOFTWARE      98566144\nSOFTWARE.LOG1 10485760\nSOFTWARE.LOG2 10485760","")],
 "Boot to Recovery and let 'chkdsk C: /f' plus a clean reboot retry the log replay; if the hive still won't load, restore it from a System Restore point or backup -- do not delete .LOG1/.LOG2 manually, they contain the newest committed data."),
("internals","ETW-based tools (WPR, xperf, some monitoring agents) fail with 'The instance name passed was not recognized'",
 "A required ETW provider's registration is corrupted or was unregistered by an uninstaller, so sessions referencing it fail to start; the provider list confirms the expected GUID is absent.",
 [("logman query providers | findstr /i 'Microsoft-Windows-DiskIO'","(provider missing from the registered list)","")],
 "Re-register the provider's manifest with 'wevtutil im <manifest.man>' from the owning feature/app, or run 'sfc /scannow' if it's an inbox provider; re-enable the Windows feature that ships the provider if it was removed."),
# ---- Event Viewer additions ----
("eventlog","Event ID 7 'The device ... has a bad block' appearing for a data drive",
 "Disk Event 7 means the drive hit an unreadable sector and remapped/failed the read at the hardware level -- direct evidence of physical media degradation on the named device, regardless of what SMART summary tools claim.",
 [("Get-WinEvent -FilterHashtable @{LogName='System'; ProviderName='disk'; Id=7} -MaxEvents 5 | Select-Object -ExpandProperty Message","The device, \\Device\\Harddisk1\\DR1, has a bad block. (5 occurrences, climbing)","")],
 "Back up that disk immediately and replace it; run 'chkdsk /r' only after backup (it stresses a failing drive). Recurring Event 7 is a physical failure signature, not something software repairs."),
("eventlog","Event ID 11 'The driver detected a controller error on \\Device\\Ide\\IdePort0'",
 "Event 11 blames the controller/channel rather than the disk platters -- classic for a failing SATA cable, port, or controller rather than the drive itself, especially when SMART on the drive stays clean.",
 [("Get-WinEvent -FilterHashtable @{LogName='System'; Id=11} -MaxEvents 5 | Select-Object -ExpandProperty Message","The driver detected a controller error on \\Device\\Ide\\IdePort0. (repeating)",""),
  ("Get-PhysicalDisk | Select-Object FriendlyName, HealthStatus","FriendlyName HealthStatus\n------------ ------------\nSamsung 860  Healthy","")],
 "Replace the SATA cable and try another motherboard port first (fixes most Event 11 storms); if errors follow the drive across ports/cables, then suspect the drive's controller board instead."),
("eventlog","Event ID 7001 'The ... service depends on the ... service which failed to start' cascades at boot",
 "Event 7001 records dependency-chain failures: one root service failing (here the Network Store Interface) cascades into every dependent service logging its own 7001 -- fix the root, and the cascade disappears.",
 [("Get-WinEvent -FilterHashtable @{LogName='System'; Id=7001} -MaxEvents 5 | Select-Object -ExpandProperty Message","DHCP Client depends on NSI; Netlogon depends on Workstation; ... (all chains lead back to nsi)","")],
 "Troubleshoot only the root service at the bottom of the dependency chain (the one with a 7000/7023 of its own); once it starts, dependent services start normally without individual fixes."),
("eventlog","Event ID 7023 'The service terminated with the following error: The parameter is incorrect'",
 "7023 means the service started then exited with a specific Win32 error; 'parameter is incorrect' here comes from a malformed value in the service's Parameters registry key written by a recent config tool.",
 [("Get-WinEvent -FilterHashtable @{LogName='System'; Id=7023} -MaxEvents 3 | Select-Object -ExpandProperty Message","The TimeBrokerSvc service terminated with the following error: The parameter is incorrect.",""),
  ("Get-ItemProperty 'HKLM:\\SYSTEM\\CurrentControlSet\\Services\\TimeBrokerSvc\\Parameters' -ErrorAction SilentlyContinue","(shows a malformed/truncated value)","")],
 "Compare the service's registry configuration against a known-good machine and correct the malformed value, or restore the key from backup; 7023's embedded error text narrows which parameter class is at fault."),
("eventlog","Security Event ID 4720 'A user account was created' appearing on a workstation where no one should create accounts",
 "4720 on a workstation outside any provisioning window is a red flag: the event's Subject shows which account performed the creation, and here it was done by a local account at 3 AM -- consistent with persistence-building after a compromise.",
 [("Get-WinEvent -FilterHashtable @{LogName='Security'; Id=4720} -MaxEvents 3 | Select-Object -ExpandProperty Message","New Account: support$ ; Subject: WORKSTATION\\localadmin ; Time: 03:12","")],
 "Treat as an incident: disable the created account, isolate the machine, review 4624/4672/4688 events around the same window to trace how the creating account was accessed, and reset its credentials."),
# ---- NTFS ----
("ntfs","Volume reports MFT corruption -- files exist but some can't be opened and chkdsk finds MFT errors",
 "The Master File Table has damaged records; chkdsk's read-only scan reports unreadable MFT segments, meaning metadata for some files is lost even though their data clusters may be intact.",
 [("chkdsk D:","Errors found in the Master File Table (MFT)... 12 unreadable file record segments.","")],
 "Back up everything readable first, then run 'chkdsk D: /f' to rebuild what's recoverable (files with destroyed records land in Found.000); recurring MFT damage on a healthy disk suggests a controller/cable issue corrupting writes."),
("ntfs","USN Journal corruption breaks backup/sync tools with 'The USN journal is invalid' errors",
 "The change journal that incremental tools rely on is damaged; tools that track changes via USN can't resume and error out rather than falling back to full scans automatically.",
 [("fsutil usn queryjournal D:","Error: The journal entry has been deleted from the journal.","")],
 "Delete and recreate the journal: 'fsutil usn deletejournal /d D:' then 'fsutil usn createjournal m=32768000 a=4096000 D:'; affected tools will do one full rescan and then resume incremental tracking."),
("ntfs","A file shows 0 bytes in Explorer but takes real disk space -- data hidden in Alternate Data Streams",
 "The file's content lives in a named NTFS alternate data stream rather than the main stream, so Explorer shows zero size; ADS is legitimate NTFS functionality but also a classic data-hiding spot.",
 [("Get-Item 'C:\\Temp\\note.txt' -Stream *","Stream    Length\n------    ------\n::$DATA        0\nhidden:$DATA 48213","")],
 "Read the stream with 'Get-Content note.txt -Stream hidden' to inspect it; remove with 'Remove-Item note.txt -Stream hidden'. Audit unexpected ADS on user-writable paths -- malware droppers use them for staging."),
("ntfs","A backup tool loops forever on a folder tree -- a junction points back into its own parent",
 "A directory junction inside the tree targets an ancestor folder, creating an infinite recursion loop for any tool that follows reparse points instead of detecting cycles.",
 [("Get-ChildItem C:\\Data -Recurse -Attributes ReparsePoint -ErrorAction SilentlyContinue | Select-Object FullName, Target","FullName            Target\n--------            ------\nC:\\Data\\Archive\\Loop C:\\Data","")],
 "Remove the looping junction ('Remove-Item C:\\Data\\Archive\\Loop' removes only the link, not the target), and configure backup tools to not follow reparse points, which also protects against future loops."),
("ntfs","Hard-linked files confuse disk usage tools -- deleting a 'copy' doesn't free space",
 "The files are hard links: multiple directory entries sharing one data extent, so space frees only when the last link is deleted -- usage tools double-count them and deletions of one name appear to 'do nothing'.",
 [("fsutil hardlink list C:\\Tools\\app\\runtime.dll","C:\\Tools\\app\\runtime.dll\nC:\\Tools\\app2\\runtime.dll\nC:\\ProgramData\\shared\\runtime.dll","")],
 "This is expected NTFS behavior (used heavily by WinSxS); to actually reclaim space, all link names must be removed. Use tools that count hard links once when auditing usage."),
("ntfs","Disk quota exceeded errors for a user even though the volume has plenty of free space",
 "Per-user NTFS quotas are enforced on this volume, and the user's charged bytes (including files they own anywhere on the volume) exceed their limit -- overall free space is irrelevant to the quota check.",
 [("fsutil quota query D:","Quota state: Enforced\nUser: CORP\\jdoe  Limit: 10 GB  Used: 10.4 GB","")],
 "Raise or remove the user's quota entry ('fsutil quota modify' or the volume's Quota tab), or have the user delete/transfer ownership of large files; quota charges follow file ownership, not folder location."),
("ntfs","ACL corruption -- Explorer's Security tab shows 'The permissions on ... are incorrectly ordered' errors",
 "The security descriptor's ACEs are stored in non-canonical order (explicit denies must precede allows, etc.), typically after a nonconforming tool wrote the ACL directly -- Windows refuses edits until order is fixed.",
 [("icacls 'D:\\Share\\Projects' /verify","D:\\Share\\Projects: The ACL is not in canonical form.","")],
 "Fix with 'icacls D:\\Share\\Projects /reset /t' (rebuilds from inheritance) if inherited permissions suffice, or reorder in the Security tab's Advanced dialog by re-applying permissions; identify and stop the tool writing broken ACLs."),
# ---- SMB ----
("smb","SMB signing mismatch -- connecting to a hardened server fails with 'The cryptographic signature is invalid'",
 "The server now requires SMB signing per new policy, and this client has signing disabled via an old registry tweak, so the security negotiation fails outright rather than falling back.",
 [("Get-SmbClientConfiguration | Select-Object RequireSecuritySignature, EnableSecuritySignature","RequireSecuritySignature EnableSecuritySignature\n------------------------ ------------------------\n                   False                   False","")],
 "Re-enable client signing: 'Set-SmbClientConfiguration -EnableSecuritySignature $true' (and remove the legacy registry tweak that disabled it); signing adds minimal overhead on modern hardware."),
("smb","Offline Files (Client-Side Caching) shows stale content and won't sync back to the server",
 "The Offline Files cache database is stuck in a conflicted state; the sync center reports conflicts but the CSC cache itself is damaged, so resolution attempts loop without writing changes server-side.",
 [("Get-Service CscService | Select-Object Status","Status\n------\nRunning","")],
 "Save copies of locally changed files first, then reinitialize the CSC cache (set HKLM\\SYSTEM\\CurrentControlSet\\Services\\CSC\\Parameters\\FormatDatabase=1 and reboot) -- this discards the cache and re-syncs cleanly from the server."),
("smb","Network discovery shows no computers in File Explorer's Network view though shares work by UNC path",
 "Discovery depends on the Function Discovery services and the network profile being Private; here the profile is Public (which disables discovery by design) after the last network change.",
 [("Get-NetConnectionProfile | Select-Object Name, NetworkCategory","Name     NetworkCategory\n----     ---------------\nHomeLAN  Public","")],
 "Set the network to Private ('Set-NetConnectionProfile -Name HomeLAN -NetworkCategory Private') and ensure Function Discovery Resource Publication / FDPHost services run; UNC paths bypass discovery, which is why they still worked."),
("smb","Share permissions vs NTFS permissions mismatch -- user has Full Control on the share but still can't write",
 "Effective access over SMB is the most restrictive combination of share and NTFS permissions: the share grants Full Control but NTFS grants only Read, so writes fail despite the generous share ACL.",
 [("Get-SmbShareAccess -Name 'TeamDocs'","AccountName        AccessRight\n-----------        -----------\nCORP\\team-users    Full",""),
  ("icacls 'D:\\Shares\\TeamDocs' | Select-String 'team-users'","CORP\\team-users:(OI)(CI)R","")],
 "Grant the group Modify at the NTFS level ('icacls D:\\Shares\\TeamDocs /grant \"CORP\\team-users:(OI)(CI)M\"'); best practice is Everyone/Authenticated Users Full at the share layer and real control via NTFS."),
# ---- Active Directory ----
("activedirectory","Two machines report SID-related trust errors after being cloned from the same image without sysprep",
 "Both clones share the same machine SID and, more critically, identical computer account credentials history -- domain trust and some security functions misbehave because the clones were never generalized with sysprep.",
 [("Get-CimInstance Win32_ComputerSystemProduct | Select-Object UUID","(identical UUID/SID lineage confirmed across both clones)","")],
 "Rebuild the clones properly: run 'sysprep /generalize' on the source image and redeploy; for the existing machines, disjoin, delete their AD computer objects, and rejoin after re-generalizing."),
("activedirectory","Kerberos fails for one service with 'duplicate SPN' errors and intermittent authentication",
 "The same ServicePrincipalName is registered on two different accounts, so the KDC issues tickets for whichever it finds first -- when it's the wrong account, the service can't decrypt the ticket and auth fails intermittently.",
 [("setspn -X","Found 1 group of duplicate SPNs:\nHTTP/intranet.corp.local registered on CORP\\svc-web-old and CORP\\svc-web","")],
 "Remove the SPN from the obsolete account ('setspn -D HTTP/intranet.corp.local svc-web-old'); duplicate SPNs must never coexist -- the intermittent pattern matches which object the KDC happened to resolve."),
("activedirectory","Applications fail LDAP binds against the Global Catalog while normal LDAP (389) works",
 "The app queries the Global Catalog on port 3268, and the only local GC-enabled DC is offline -- regular LDAP on 389 still answers from a non-GC DC, which is why only GC-dependent lookups fail.",
 [("Test-NetConnection dc01.corp.local -Port 3268","TcpTestSucceeded : False",""),
  ("Test-NetConnection dc01.corp.local -Port 389","TcpTestSucceeded : True","")],
 "Bring the GC DC back online or enable the GC role on another local DC (NTDS Settings > Global Catalog checkbox), then allow replication to complete; site designs should always include at least two GCs."),
("activedirectory","A branch office Read-Only Domain Controller (RODC) can't authenticate some users when the WAN is down",
 "The RODC only caches passwords for accounts in its Password Replication Policy allow list; users outside it require a writable DC over the WAN, so they fail exactly when the WAN link is down.",
 [("Get-ADDomainControllerPasswordReplicationPolicy -Identity RODC01 -Allowed | Measure-Object","Count : 12 (branch has 45 active users)","")],
 "Add the branch users' group to the RODC's allowed Password Replication Policy and pre-populate their secrets ('repadmin /rodcpwdrepl'); only cached accounts survive WAN outages by design."),
# ---- DNS ----
("dns-advanced","Reverse DNS lookups fail (PTR records missing) breaking tools that resolve IPs to names",
 "The forward zone is healthy but no reverse lookup zone exists for the subnet, so PTR queries have nowhere to land -- reverse zones are never created automatically.",
 [("Resolve-DnsName -Name 10.0.2.45 -Type PTR","Resolve-DnsName : DNS name does not exist","")],
 "Create the reverse zone (2.0.10.in-addr.arpa) on the DNS server, enable secure dynamic updates so clients register their own PTRs, and add static PTRs for servers/printers with static IPs."),
("dns-advanced","Stale DNS records accumulate -- offline machines still resolve because scavenging never runs",
 "Aging/scavenging is disabled on the zone, so dynamically registered records persist forever after machines are gone; lookups keep resolving to dead IPs.",
 [("Get-DnsServerZoneAging -Name corp.local","AgingEnabled : False","")],
 "Enable aging on the zone and scavenging on the server ('Set-DnsServerZoneAging corp.local -Aging $true' plus Set-DnsServerScavenging with sensible no-refresh/refresh intervals matched to DHCP lease duration); verify timestamps before first scavenge so valid records aren't purged."),
("dns-advanced","Domain controller SRV records missing from DNS -- clients can't locate DCs after a DNS rebuild",
 "The _ldap/_kerberos SRV records under _msdcs were lost in the zone rebuild, and clients discover DCs exclusively through them -- without SRVs, domain operations fail even though A records exist.",
 [("Resolve-DnsName -Type SRV _ldap._tcp.dc._msdcs.corp.local","Resolve-DnsName : DNS name does not exist","")],
 "On each DC, restart the Netlogon service ('Restart-Service Netlogon') which re-registers all its SRV records automatically; verify with the same SRV query, and check the zone allows secure dynamic updates."),
("dns-advanced","Secondary DNS server's zone is stale -- zone transfers (AXFR/IXFR) are being refused",
 "The primary's zone-transfer settings don't include the new secondary's IP, so transfer requests are refused and the secondary keeps serving its aging copy until expiry.",
 [("Get-DnsServerZone corp.local | Select-Object SecureSecondaries, SecondaryServers","SecureSecondaries    SecondaryServers\n------------------    ----------------\nTransferToSecureServers {10.0.1.10} (new secondary 10.0.1.11 missing)","")],
 "Add the new secondary's IP to the allowed transfer list ('Set-DnsServerPrimaryZone corp.local -SecondaryServers 10.0.1.10,10.0.1.11 -SecureSecondaries TransferToSecureServers') and trigger a transfer from the secondary."),
("dns-advanced","DNSSEC validation failures -- some external domains fail with SERVFAIL only through the internal resolver",
 "The internal resolver has DNSSEC validation enabled and its trust anchor for the root zone is outdated (missed the KSK rollover), so signed domains fail validation while unsigned ones resolve fine.",
 [("Resolve-DnsName cloudflare.com -Server 10.0.0.5","Resolve-DnsName : ... SERVFAIL",""),
  ("Get-DnsServerTrustAnchor -Name . | Select-Object KeyTag","KeyTag : 19036 (superseded root KSK)","")],
 "Update the root trust anchor to the current KSK ('Add-DnsServerTrustAnchor -Root' after enabling automatic RFC 5011 rollover support), then clear the resolver cache; keep automatic trust-anchor updates on."),
# ---- DHCP ----
("dhcp","PXE boot fails -- clients don't receive boot server info though DHCP addressing works",
 "DHCP options 66 (boot server) and 67 (boot file name) aren't set on the scope, so PXE clients get an IP but no next-server/boot path -- addressing and PXE bootstrap are separate option sets.",
 [("Get-DhcpServerv4OptionValue -ScopeId 10.0.2.0 | Where-Object OptionId -in 66,67","(no output -- options not configured)","")],
 "Set option 66 to the WDS/SCCM PXE server's FQDN and 67 to the boot file (e.g., smsboot\\x64\\wdsmgfw.efi for UEFI) -- or better, configure IP helpers on routers to forward PXE broadcasts natively, which handles BIOS/UEFI differences more reliably than static options."),
("dhcp","DHCP failover partners show different lease data -- clients get NAKs when the partner answers",
 "The failover relationship is out of sync (partner state COMMUNICATION_INTERRUPTED); each server holds divergent lease tables, so a renewal answered by the wrong partner produces a NAK.",
 [("Get-DhcpServerv4Failover | Select-Object Name, State","Name          State\n----          -----\nHQ-Failover   CommunicationInterrupted","")],
 "Restore connectivity between the DHCP partners (port 647 TCP), then resynchronize the relationship ('Invoke-DhcpServerv4FailoverReplication'); investigate what broke the partner channel -- often a firewall change."),
("dhcp","Users intermittently get addresses from an unauthorized (rogue) DHCP server on the LAN",
 "A consumer router someone plugged in is answering DHCP DISCOVER faster than the corporate server for nearby clients, handing out its own subnet -- classic rogue DHCP symptom pattern (wrong gateway/subnet on affected machines).",
 [("Get-WinEvent -FilterHashtable @{LogName='System'; ProviderName='Microsoft-Windows-Dhcp-Client'} -MaxEvents 5 | Select-Object -ExpandProperty Message","Lease obtained from server 192.168.0.1 (not the corporate 10.0.0.10)","")],
 "Locate and remove the rogue device (trace the offending server's MAC via switch tables), and enable DHCP snooping on managed switches so only authorized ports may answer DHCP -- the durable fix against repeats."),
# ---- IIS ----
("iis","A site binding conflict in HTTP.sys -- 'The process cannot access the file because it is being used by another process' on site start",
 "HTTP.sys already has the port reserved by another process/URL ACL, so IIS can't add its binding -- with HTTP.sys the conflict is at the kernel URL-reservation layer, not a file at all despite the message.",
 [("netsh http show servicestate | findstr ':443'","URL group with 0.0.0.0:443 registered to PID 3120 (a third-party agent)","")],
 "Stop/reconfigure the conflicting process (or remove its stale reservation with 'netsh http delete urlacl'), then start the IIS site; two listeners can't own the same IP:port:host combination in HTTP.sys."),
("iis","Windows Process Activation Service (WAS) won't start, taking all IIS sites down",
 "WAS fails with a corrupted configuration error -- applicationHost.config has an XML syntax error introduced by a manual edit, and WAS (which parses it before W3SVC can run) refuses to start.",
 [("Get-Service WAS, W3SVC | Select-Object Name, Status","Name  Status\n----  ------\nWAS   Stopped\nW3SVC Stopped",""),
  ("Get-WinEvent -FilterHashtable @{LogName='System'; ProviderName='Microsoft-Windows-WAS'} -MaxEvents 2","Configuration error: applicationHost.config line 412: unexpected end tag","")],
 "Fix the XML at the reported line (or restore applicationHost.config from 'C:\\inetpub\\history\\' which keeps automatic versioned backups), then start WAS and W3SVC."),
("iis","ASP.NET Core app returns 500.30 'ANCM In-Process Start Failure' in IIS",
 "The ASP.NET Core Module launched the app in-process and it crashed during startup; stdout logging (disabled by default) captured a missing environment variable that only exists on the dev machine.",
 [("Get-Content 'C:\\inetpub\\app\\logs\\stdout_*.log' -Tail 5","Unhandled exception: InvalidOperationException: Connection string 'Main' not found.","")],
 "Enable stdout logging in web.config to capture startup errors, then provide the missing configuration (connection string/env var) via appsettings.Production.json or the app pool's environment settings; disable stdout logging again after diagnosis."),
("iis","HTTPS works for one site but a second site on the same IP serves the wrong certificate (SNI misconfiguration)",
 "The second site's binding wasn't created with 'Require SNI', so it fell back to the IP-bound default cert -- with multiple TLS sites per IP, every binding except at most one default must use SNI.",
 [("netsh http show sslcert | findstr /C:'0.0.0.0:443' /C:'Hostname'","IP:port 0.0.0.0:443 (one legacy IP binding) + hostname bindings missing for site2.corp.com","")],
 "Recreate site2's HTTPS binding with the hostname filled in and 'Require Server Name Indication' checked, bound to its own certificate; keep only one (or zero) non-SNI fallback binding per IP:port."),
("iis","Enabling HSTS -- but the site keeps redirecting HTTP to HTTPS inconsistently and browsers don't remember",
 "The Strict-Transport-Security header is only being sent on some responses because it's configured on a subfolder's web.config, not site-wide, so browsers never durably record the HSTS policy.",
 [("Invoke-WebRequest https://site.corp.com -MaximumRedirection 0 | Select-Object -ExpandProperty Headers","(Strict-Transport-Security header absent on root responses)","")],
 "Configure HSTS at the site level (IIS 10.0+ has native HSTS settings on the site's HSTS dialog; enable includeSubDomains and an appropriate max-age), and keep exactly one canonical HTTP-to-HTTPS redirect rule."),
# ---- Certificates ----
("certificates","Clients report 'certificate chain incomplete' for a site whose cert is valid -- missing intermediate CA",
 "The server sends only the leaf certificate; clients that lack the intermediate cached fail chain building, while machines that happened to cache it earlier succeed -- classic missing-intermediate deployment error.",
 [("certutil -verify -urlfetch site.cer | findstr /i 'chain'","A certificate chain could not be built to a trusted root authority (missing intermediate: CorpIssuingCA2)","")],
 "Install the intermediate CA cert into the server's Intermediate Certification Authorities store (or re-import the full PFX chain) so the server presents the complete chain during the TLS handshake."),
("certificates","A certificate exists but the service can't use it -- 'the credentials supplied to the package were not recognized' (private key missing)",
 "The certificate's private key is absent (imported from a .cer instead of a .pfx), so any service trying to use it for TLS fails -- the public certificate alone can't terminate connections.",
 [("Get-ChildItem Cert:\\LocalMachine\\My | Where-Object Subject -like '*svc.corp.com*' | Select-Object HasPrivateKey","HasPrivateKey\n--------------\n        False","")],
 "Re-import the certificate from its .pfx (which contains the private key) with the correct password, or if the key was generated on this machine, run 'certutil -repairstore my <thumbprint>' to relink the orphaned key."),
("certificates","PFX import fails with 'The password you entered is incorrect' though the password is definitely right",
 "The PFX was exported on a newer system using AES-256 encryption, and this legacy server's crypto stack can't decrypt AES-encrypted PFX files -- the misleading 'wrong password' error masks the algorithm mismatch.",
 [("certutil -dump cert.pfx | findstr /i 'algorithm'","Encryption algorithm: AES256-SHA256 (unsupported on this OS build)","")],
 "Re-export the PFX with legacy TripleDES-SHA1 compatibility (the 'Enable certificate privacy' checkbox unticked / '-CryptoAlgorithmOption TripleDES_SHA1' in Export-PfxCertificate), or update/replace the legacy target system."),
("certificates","Certificate auto-enrollment silently stopped -- machine certs expire without renewal",
 "Autoenrollment GPO is enabled but the certificate template's permissions no longer grant this computer group Enroll/Autoenroll after a template modification -- clients poll, find nothing permitted, and log nothing visible.",
 [("certutil -pulse","Certificate enrollment initiated (completed with no certificates issued)",""),
  ("Get-WinEvent -FilterHashtable @{LogName='Application'; ProviderName='Microsoft-Windows-CertificateServicesClient-CertEnroll'} -MaxEvents 3","Enrollment for template 'CorpMachine' failed: access denied","")],
 "Restore Enroll + Autoenroll permissions for the computers' group on the certificate template (Certification Authority console > template Security tab), then 'certutil -pulse' on clients to trigger immediate re-enrollment."),
# ---- VPN ----
("vpn","L2TP/IPsec VPN fails behind home routers with error 809 -- no response from server",
 "Error 809 means the IPsec negotiation packets never made it through: the NAT router isn't passing ESP/UDP 4500 properly, and Windows by default won't attempt IPsec over double-NAT without the NAT-T registry setting.",
 [("Get-ItemProperty 'HKLM:\\SYSTEM\\CurrentControlSet\\Services\\PolicyAgent' -Name AssumeUDPEncapsulationContextOnSendRule -ErrorAction SilentlyContinue","(value not present)","")],
 "Set AssumeUDPEncapsulationContextOnSendRule=2 under PolicyAgent and reboot (enables NAT-T through double NAT), confirm UDP 500/4500 pass the router, and prefer IKEv2/SSTP where possible -- they traverse NAT far better."),
("vpn","SSTP VPN fails with error 0x80092013 'The revocation function was unable to check revocation'",
 "SSTP validates the server certificate's revocation over HTTP before the tunnel exists; on this network the CRL URL is only reachable through the tunnel, creating a chicken-and-egg failure.",
 [("certutil -URL http://crl.corp.com/pki/corp-ca.crl","(retrieval fails from the pre-tunnel network)","")],
 "Publish the CRL on an internet-reachable endpoint (standard practice for SSTP deployments); as a stopgap only, clients can set NoCertRevocationCheck=1 for SSTP -- but fixing CRL reachability is the correct solution."),
("vpn","IKEv2 VPN connects but no traffic flows -- small packets work, large transfers stall (MTU blackhole)",
 "The tunnel adds encapsulation overhead and an upstream device drops ICMP 'fragmentation needed', so Path MTU Discovery fails -- TCP handshakes (small) succeed while full-size packets vanish.",
 [("ping -f -l 1350 intranet.corp.local","Reply from 10.0.0.5 (success at 1350)",""),
  ("ping -f -l 1400 intranet.corp.local","Request timed out (blackhole above ~1350)","")],
 "Lower the VPN interface MTU to the discovered working size ('netsh interface ipv4 set subinterface \"VPN\" mtu=1350 store=persistent'), and/or enable MSS clamping on the VPN server so all TCP flows self-adjust."),
("vpn","Always On VPN user tunnel never auto-connects for some users after deployment",
 "The AOVPN profile's trigger relies on the user certificate, and affected users' certs were issued from a template missing the Client Authentication EKU -- the tunnel silently declines to trigger without a valid auth cert.",
 [("Get-ChildItem Cert:\\CurrentUser\\My | Select-Object Subject, EnhancedKeyUsageList","Subject: CN=jdoe ... EKU: Encrypting File System (Client Authentication missing)","")],
 "Fix the certificate template to include Client Authentication EKU and re-enroll affected users; AOVPN user tunnels require a client-auth-capable certificate for both triggering and EAP authentication."),
# ---- Wi-Fi ----
("wifi","WPA2-Enterprise (802.1X) Wi-Fi fails with 'Can't connect to this network' after a NPS server certificate renewal",
 "Clients validate the RADIUS server's certificate; the renewed NPS cert came from a different CA than the one configured in the Wi-Fi profile's trusted root list, so clients correctly refuse authentication.",
 [("netsh wlan export profile name='CorpWiFi' folder=C:\\temp; Select-String -Path C:\\temp\\*.xml -Pattern 'TrustedRootCA'","TrustedRootCA hash matches the OLD issuing CA only","")],
 "Update and redeploy the Wi-Fi profile (GPO/Intune) with the new issuing CA in the trusted roots for server validation, or reissue the NPS certificate from the originally trusted CA; never train users to click through server-validation failures."),
("wifi","Wi-Fi drops every time weather radar is nearby -- 5 GHz DFS channel interruptions",
 "The AP uses DFS channels which must vacate immediately when radar signatures are detected; each detection forces a channel switch that clients experience as a drop -- environmental/regulatory behavior, not a fault.",
 [("netsh wlan show interfaces | findstr 'Channel'","Channel: 100 (a DFS-range channel)","")],
 "Configure the AP to prefer non-DFS channels (36-48, 149-165 where permitted) if drops are frequent at this location; DFS channels offer cleaner spectrum but carry mandatory radar-vacate behavior."),
("wifi","A device can't join Wi-Fi -- MAC filtering blocks it because MAC randomization gives a new address",
 "Windows' random hardware address feature presents a per-network randomized MAC, which doesn't match the address whitelisted in the router's MAC filter -- each 'Forget'/'re-add cycle can generate yet another address.",
 [("netsh wlan show interfaces | findstr 'Physical'","Physical address: 8a:xx:xx:xx:xx:xx (locally administered/randomized)","")],
 "Either disable random hardware addresses for this network (Wi-Fi network Properties toggle) and whitelist the true MAC, or preferably drop MAC filtering entirely -- it adds admin burden with negligible security value."),
# ---- Hyper-V ----
("hyperv","Hyper-V Live Migration fails with 'The credentials supplied to the package were not recognized' between two hosts",
 "Live Migration over Kerberos requires constrained delegation configured on both hosts' computer accounts for the cifs and 'Microsoft Virtual System Migration Service' services -- one host is missing the delegation entries.",
 [("Get-ADComputer HV02 -Properties msDS-AllowedToDelegateTo | Select-Object -ExpandProperty msDS-AllowedToDelegateTo","(list missing 'Microsoft Virtual System Migration Service/HV01')","")],
 "Add matching constrained delegation entries (use Kerberos-only) on both host computer accounts for each other's migration and cifs services, or switch migration authentication to CredSSP (requires initiating from a console session)."),
("hyperv","A VM's checkpoint won't merge -- disk space fills up as .avhdx files keep growing",
 "The checkpoint's background merge stalled because the volume has too little free space for the merge working set; the .avhdx chain keeps absorbing writes and consuming space, worsening the shortage in a feedback loop.",
 [("Get-VMSnapshot -VMName SQLVM | Select-Object Name, CreationTime","Name: Pre-Update (created 47 days ago, never deleted)",""),
  ("Get-Volume -DriveLetter V | Select-Object SizeRemaining","SizeRemaining : 18 GB (chain needs ~60 GB to merge)","")],
 "Free or add space on the volume (move another VM's files off temporarily), then delete the checkpoint so the merge can complete; adopt a policy of removing checkpoints within days -- they're not backups."),
("hyperv","Dynamic Memory VM gets stuck at its startup RAM and performance craters under load",
 "Dynamic Memory ballooning requires the guest's Hyper-V memory integration component; this guest's integration services are outdated/disabled, so the host can never expand the VM beyond startup RAM.",
 [("Get-VMMemory -VMName AppVM | Select-Object DynamicMemoryEnabled, Startup, Maximum","DynamicMemoryEnabled Startup     Maximum\n--------------------- -------     -------\n                True  2147483648  17179869184",""),
  ("Get-VMIntegrationService -VMName AppVM | Where-Object Name -like '*Memory*' | Select-Object Enabled, PrimaryStatusDescription","Enabled PrimaryStatusDescription\n------- -------------------------\n  False (disabled)","")],
 "Enable the memory integration service ('Enable-VMIntegrationService -VMName AppVM -Name \"Dynamic Memory\"') and update guest integration components via Windows Update in the guest; verify demand-based expansion resumes under load."),
("hyperv","A Generation 1 VM can't boot from a copied disk that works in a Generation 2 VM",
 "Gen1 VMs boot via BIOS/MBR while Gen2 requires UEFI/GPT: the disk is GPT-partitioned with an EFI system partition, which Gen1's emulated BIOS can't boot -- the generations aren't interchangeable at the firmware level.",
 [("Get-VHD 'V:\\disks\\app.vhdx' | Select-Object VhdFormat; Get-Disk -Number 5 | Select-Object PartitionStyle","VhdFormat: VHDX; PartitionStyle: GPT","")],
 "Attach the disk to a Generation 2 VM (matching its UEFI/GPT layout), or convert the OS image to MBR/BIOS boot with MBR2GPT-in-reverse tooling/reinstall if Gen1 is truly required (legacy OSes only)."),
# ---- Docker/WSL ----
("docker","docker compose up fails with 'network ... overlaps with other one on this address space'",
 "Compose's default bridge subnet collides with the corporate VPN's routes; Docker refuses to create a network whose range overlaps an existing route, and the VPN owns that space on this machine.",
 [("docker network inspect bridge --format '{{json .IPAM.Config}}'","[{\"Subnet\":\"172.17.0.0/16\"}] (VPN also routes 172.17.0.0/16)","")],
 "Set a non-conflicting address pool in Docker's daemon settings ('default-address-pools' e.g. 10.200.0.0/16) and explicit subnets in compose networks; pick ranges the VPN never routes."),
("docker","Switching between Windows containers and Linux containers breaks builds with 'no matching manifest for windows/amd64'",
 "The daemon is in Windows-containers mode while the compose/build references Linux-only images; each mode can only run its own OS's images, and the error is the registry saying no Windows variant exists for that image.",
 [("docker version --format '{{.Server.Os}}'","windows","")],
 "Switch Docker Desktop back to Linux containers mode for Linux images (or use '--platform linux/amd64' with WSL2 backend which runs both via integration); keep separate compose files if genuinely mixing Windows and Linux workloads."),
("wsl","WSL2 DNS resolution fails inside distros while Windows resolves fine",
 "WSL2 generates /etc/resolv.conf pointing at the Windows host's virtual DNS proxy, and a VPN client's firewall rules block the WSL NAT subnet from reaching it -- Linux-side DNS dies whenever the VPN is up.",
 [("wsl cat /etc/resolv.conf","nameserver 172.28.144.1 (unreachable from inside WSL while VPN active)","")],
 "Create /etc/wsl.conf with 'generateResolvConf=false', write a static resolv.conf (corporate DNS or 1.1.1.1 per policy), and/or allow the WSL subnet through the VPN client's firewall; 'wsl --shutdown' applies changes."),
("wsl","WSL2 GPU acceleration (CUDA) not available inside the distro though the Windows driver is installed",
 "GPU-PV into WSL requires the Windows GPU driver with WSL support, the WSL kernel to be current, and no 'nvidia' Linux driver installed inside the distro (the in-guest driver conflicts with the paravirtual path).",
 [("wsl nvidia-smi","NVIDIA-SMI has failed because it couldn't communicate with the NVIDIA driver",""),
  ("wsl --version","WSL version: 1.0.3 (kernel outdated)","")],
 "Run 'wsl --update' for the current kernel, install the latest Windows NVIDIA driver (which ships the WSL CUDA stack), and remove any 'nvidia-*' driver packages installed inside the distro -- only CUDA toolkit belongs in-guest."),
("wsl","Enabling systemd in WSL2 broke a distro -- it hangs at startup after editing wsl.conf",
 "systemd=true requires a recent WSL release; on this older installed WSL version the flag causes the init handoff to hang, so the distro never reaches a shell.",
 [("wsl --version","WSL version: 0.70.8 (predates stable systemd support)","")],
 "Update WSL from the Store ('wsl --update' or reinstall the WSL app), then re-enable systemd in /etc/wsl.conf and 'wsl --shutdown'; on unupdatable setups, remove the systemd flag to restore startup."),
# ---- PowerShell platform ----
("powershell","Scripts behave differently after AppLocker rollout -- PowerShell runs in Constrained Language Mode",
 "AppLocker/WDAC script enforcement drops interactive PowerShell to ConstrainedLanguage for unapproved scripts, disabling .NET method calls and Add-Type -- scripts that worked before now fail with method-invocation errors.",
 [("$ExecutionContext.SessionState.LanguageMode","ConstrainedLanguage","")],
 "Sign/authorize the scripts through the AppLocker/WDAC policy (approved scripts run FullLanguage automatically); don't chase individual method errors -- language mode is the systemic cause, and policy authorization is the fix."),
("powershell","A module works in Windows PowerShell 5.1 but fails to import in PowerShell 7",
 "The module relies on .NET Framework-only APIs, and PowerShell 7 (running .NET Core/.NET) can't load them natively -- the import fails or the module misbehaves despite both consoles looking similar.",
 [("pwsh -c \"Import-Module LegacyCorpModule\"","Import-Module: Could not load type 'System.Web.Something' from assembly...","")],
 "Import it through the compatibility layer ('Import-Module LegacyCorpModule -UseWindowsPowerShell'), which proxies via a background 5.1 session -- or run that workload in 5.1 outright; check for a modernized module version."),
("powershell","Second-hop failures -- remote session can't access a file share (credential delegation)",
 "Inside a PSRemoting session, the credential can't hop to a third machine (classic double-hop): the share denies access even though the same user direct-from-desktop succeeds.",
 [("Invoke-Command -ComputerName APP01 -ScriptBlock { Test-Path '\\\\FS01\\data' }","False (Access denied inside the remote session)","")],
 "Use resource-based constrained delegation (set PrincipalsAllowedToDelegateToAccount on FS01's computer object for APP01), or CredSSP where policy allows; RBCD is the modern, safer answer to double-hop."),
("powershell","JEA endpoint users can't run the commands they were promised -- 'not recognized' inside the constrained session",
 "The JEA role capability file lists the cmdlets, but the session configuration doesn't import the module that ships them -- visibleCmdlets only filters what's already loadable, it doesn't install anything.",
 [("Get-PSSessionCapability -ConfigurationName SupportOps -Username corp\\helpdesk | Select-Object -First 5 Name","(target cmdlets absent from the capability list)","")],
 "Add 'ModulesToImport' for the needed modules in the role capability (.psrc), re-register the session configuration, and re-test with Get-PSSessionCapability -- it shows exactly what a connecting user will see."),
# ---- BitLocker ----
("bitlocker","BitLocker demands recovery key after every BIOS update -- TPM PCR mismatch",
 "The default PCR validation profile includes firmware measurements that change with every BIOS update, so the TPM correctly refuses auto-unlock until re-sealed -- expected security behavior, manageable operationally.",
 [("manage-bde -protectors -get C:","TPM protector PCR validation profile: 0, 2, 4, 11","")],
 "Before planned firmware updates, suspend BitLocker ('Suspend-BitLocker -MountPoint C: -RebootCount 1') so the update boots without a recovery prompt and protection auto-resumes re-sealed to the new measurements."),
("bitlocker","BitLocker Network Unlock isn't working -- wired machines still prompt for PIN at boot",
 "Network Unlock requires the WDS-hosted unlock server, DHCP on the boot NIC, the Network Unlock certificate deployed, and UEFI DHCP boot support -- the client here never gets a DHCP lease during pre-boot because the NIC's UEFI network stack is disabled.",
 [("manage-bde -protectors -get C: | findstr 'Network'","(TpmPin + Network Unlock protectors both present)","")],
 "Enable the UEFI network stack (IPv4 PXE support) in firmware setup so pre-boot DHCP works; verify the Network Unlock server's port 5052/UDP reachability from the client VLAN -- with those in place, PIN is only needed off-network."),
("bitlocker","BitLocker encryption is stuck 'paused' at a fixed percentage and never resumes",
 "Encryption auto-paused due to bad sectors detected on the volume mid-conversion; BitLocker won't resume until the underlying disk errors are addressed, silently waiting rather than surfacing a clear error.",
 [("Get-BitLockerVolume -MountPoint D: | Select-Object VolumeStatus, EncryptionPercentage","VolumeStatus      EncryptionPercentage\n------------      ---------------------\nEncryptionPaused  63.4",""),
  ("Get-WinEvent -FilterHashtable @{LogName='System'; ProviderName='disk'; Id=7} -MaxEvents 2","Bad block events on the same volume's disk","")],
 "Run 'chkdsk D: /r' to map out bad sectors, then 'Resume-BitLocker -MountPoint D:'; if bad blocks keep appearing, the drive is failing -- move data and encrypt a replacement instead."),
# ---- Store / winget ----
("windows","winget fails with 'Failed in attempting to update the source: winget' -- can't install anything",
 "The winget source's index download is failing through the corporate proxy: the CDN URL isn't in the proxy allow list, so every operation that refreshes the source errors out before install logic even runs.",
 [("winget source list","winget  https://cdn.winget.microsoft.com/cache (Last update failed)","")],
 "Have the proxy allow cdn.winget.microsoft.com (and *.microsoft.com Store endpoints), or configure winget's proxy support; then 'winget source reset --force' and retry."),
("windows","Microsoft Store 'App Installer' won't update, blocking .msixbundle installs with an appinstaller version error",
 "Sideloaded .msixbundle installs require a current App Installer, but its own update comes from the Store, which is blocked by policy on this machine -- a circular dependency until App Installer is updated out-of-band.",
 [("Get-AppxPackage Microsoft.DesktopAppInstaller | Select-Object Version","Version : 1.16.x (current requirement is 1.21+)","")],
 "Download the current DesktopAppInstaller .msixbundle from Microsoft's official distribution (or via winget-cli GitHub releases) and install with Add-AppxPackage; then the dependent packages install normally."),
# ---- M365 ----
("office","Outlook keeps prompting for password after tenant enables Modern Authentication",
 "Outlook is falling back to legacy basic auth because the local EnableADAL/AllowBasic overrides force old behavior -- the tenant now rejects basic auth, producing endless prompts instead of the modern auth browser flow.",
 [("Get-ItemProperty 'HKCU:\\Software\\Microsoft\\Office\\16.0\\Common\\Identity' -Name EnableADAL -ErrorAction SilentlyContinue","EnableADAL : 0 (legacy override present)","")],
 "Remove the EnableADAL=0 override (modern auth is default-on in current Office), restart Outlook, and complete the interactive Azure AD sign-in; audit for old GPOs still deploying legacy auth registry values."),
("office","A shared mailbox stopped auto-mapping in Outlook for one user while others see it fine",
 "Auto-mapping ties to the msExchDelegateListLink attribute written when Full Access was granted; this user's permission was re-granted through a group, and group-based Full Access doesn't trigger auto-mapping.",
 [("Get-MailboxPermission shared@corp.com | Where-Object {$_.User -like '*jdoe*'}","(no direct entry -- access flows via a security group)","")],
 "Either add the mailbox manually in Outlook (File > Account Settings > More Settings > Advanced), or grant the user direct Full Access with automapping ('Add-MailboxPermission shared -User jdoe -AccessRights FullAccess -AutoMapping $true')."),
# ---- Azure/Entra ----
("azuread","Hybrid Azure AD Join stuck 'pending' -- dsregcmd shows the device isn't registering",
 "The device can't reach the Azure AD device registration endpoint through the proxy, so the scheduled registration task fails silently and the computer object never converts from 'pending'.",
 [("dsregcmd /status | Select-String 'AzureAdJoined|WorkplaceJoined'","AzureAdJoined : NO",""),
  ("Test-NetConnection login.microsoftonline.com -Port 443","TcpTestSucceeded : False (through system proxy context)","")],
 "Allow the device-registration URLs (login.microsoftonline.com, device.login.microsoftonline.com, enterpriseregistration.windows.net) for machine-context traffic through the proxy (WPAD/system proxy), then re-run the Workplace Join scheduled task or 'dsregcmd /join'."),
("azuread","Users blocked by Conditional Access with 'You can't get there from here' on compliant-looking devices",
 "The CA policy requires a compliant device, but these devices' Intune compliance state is 'Not evaluated' -- their MDM sync has been failing, so Azure AD sees no compliance claim and correctly blocks.",
 [("dsregcmd /status | Select-String 'MdmUrl'","MdmUrl : (empty -- MDM enrollment broken)","")],
 "Fix the MDM enrollment (re-enroll via Settings > Access work or school, or repair the Intune enrollment scheduled tasks), force a sync, and confirm the device flips to Compliant in Intune -- CA unblocks automatically after that."),
("azuread","Windows Autopilot device hangs at 'Securing your hardware' during pre-provisioning",
 "That phase is TPM attestation: this device's TPM firmware version has a known attestation bug, so the attestation call loops until timeout -- a device-firmware issue, not an Autopilot profile problem.",
 [("Get-Tpm | Select-Object ManufacturerVersion","ManufacturerVersion : 7.2.170.1 (known attestation-broken release)","")],
 "Update the TPM firmware from the OEM's tool to the fixed version, clear the TPM, and re-run pre-provisioning; check the OEM's Autopilot attestation advisory list before large rollouts."),
# ---- BIOS/Firmware ----
("firmware","PC loses BIOS settings and shows 'CMOS checksum error - Defaults loaded' at every cold boot",
 "The CMOS checksum failing every cold boot means the settings RAM loses power -- the classic dead CR2032 coin cell; settings survive warm reboots (standby power) but die when AC is removed.",
 [("Get-Date","(system date reverted to firmware default epoch after cold start)","")],
 "Replace the CR2032 battery, restore BIOS settings (boot order, XMP, virtualization), and resync the clock; if the error persists with a new battery, the board's RTC circuit needs service."),
("firmware","Wake-on-LAN stopped working after upgrading to a new machine with Modern Standby",
 "Modern Standby platforms handle wake sources differently: the NIC's WOL from the S0 low-power idle requires both the adapter's WOL settings and the platform's 'network connectivity in standby' allowance -- disabled here by default on battery.",
 [("powercfg /a","Standby (S0 Low Power Idle) Network Connected available",""),
  ("Get-NetAdapterPowerManagement -Name Ethernet | Select-Object WakeOnMagicPacket","WakeOnMagicPacket : Disabled","")],
 "Enable magic-packet wake on the adapter ('Enable-NetAdapterPowerManagement -Name Ethernet -WakeOnMagicPacket'), and in firmware enable WOL; on Modern Standby laptops also allow network connectivity in standby (on AC at minimum)."),
("firmware","After a microcode-updating Windows patch, an older CPU shows measurable performance regression",
 "The patch delivered a security microcode update whose mitigations cost performance on this CPU generation -- an intentional security/performance trade-off, documented per-vulnerability by Microsoft and the CPU vendor.",
 [("Get-CimInstance Win32_Processor | Select-Object Name","Name: Intel(R) Core(TM) i7-6700K (older generation, mitigation-heavy)","")],
 "Keep the mitigations (recommended); if a controlled/air-gapped workload justifies it, specific mitigations can be disabled via documented registry switches -- document the risk acceptance and never do this on internet-facing machines."),
# ---- Hardware ----
("hardware","One RAM slot no longer works -- installed memory shows half the expected total",
 "Windows sees only one of two installed modules; swapping the sticks proves both modules work individually in the good slot, isolating the fault to the physical slot/board traces.",
 [("Get-CimInstance Win32_PhysicalMemory | Measure-Object Capacity -Sum","Sum : 8589934592 (one 8 GB module of the 16 GB installed)","")],
 "Verify seating first, test each stick alone in each slot to confirm the dead slot, and update BIOS (memory-training fixes are common); a persistently dead slot is a motherboard repair/replace decision."),
("hardware","NVMe SSD performance collapses during long transfers -- thermal throttling suspected",
 "The NVMe drive hits its thermal limit under sustained writes and throttles hard; performance recovers after cool-down, matching the temperature-driven pattern rather than a firmware or driver fault.",
 [("Get-PhysicalDisk | Get-StorageReliabilityCounter | Select-Object DeviceId, Temperature","DeviceId Temperature\n-------- -----------\n2                 84","")],
 "Add a motherboard M.2 heatsink/thermal pad (or improve case airflow over the slot); sustained 80C+ triggers throttling on most controllers -- after cooling, verify with the same counter under load."),
("hardware","USB-C dock intermittently drops power delivery -- laptop flips between charging and battery",
 "The dock's USB-C PD negotiation keeps renegotiating (marginal cable or dock firmware), and each renegotiation momentarily drops the power contract -- the same flapping pattern as a failing barrel charger, PD-style.",
 [("Get-WinEvent -FilterHashtable @{LogName='System'; ProviderName='Microsoft-Windows-Kernel-Power'; Id=105} -MaxEvents 10","10 AC/DC transitions in 15 minutes, all while docked","")],
 "Use the e-marked cable shipped with the dock (or a certified 100 W cable), update the dock's firmware, and try another laptop port; persistent flapping with known-good cable and firmware means the dock's PD controller is failing."),
("hardware","Built-in SD card reader stopped appearing after a driver cleanup utility ran",
 "The reader's PCIe device is present but bound to no driver (the cleanup removed the vendor package and no inbox driver matches), so it silently vanishes from Explorer rather than erroring.",
 [("Get-PnpDevice | Where-Object InstanceId -like 'PCI\\VEN_10EC&DEV_522A*' | Select-Object Status, FriendlyName","Status  FriendlyName\n------  ------------\nUnknown PCI Device","")],
 "Reinstall the card reader driver (Realtek PCIe card reader package from the laptop vendor); avoid third-party 'driver cleanup' utilities -- they routinely strip working OEM drivers that Windows can't replace inbox."),
# ---- AI / Developer machines ----
("aidev","Ollama service won't start on Windows -- 'bind: Only one usage of each socket address' on port 11434",
 "Another process (a previous orphaned ollama.exe) still holds port 11434, so the new service instance can't bind and exits immediately.",
 [("Get-NetTCPConnection -LocalPort 11434 | Select-Object OwningProcess","OwningProcess\n--------------\n         8812",""),
  ("Get-Process -Id 8812 | Select-Object Name","Name\n----\nollama","")],
 "Kill the orphaned process ('Stop-Process -Id 8812 -Force') and restart Ollama; if you need a different port, set OLLAMA_HOST (e.g., 127.0.0.1:11500) for the service and clients."),
("aidev","CUDA not detected by PyTorch on a machine with an NVIDIA GPU -- torch.cuda.is_available() returns False",
 "The installed PyTorch wheel is the CPU-only build; the GPU and driver are fine, but the framework itself has no CUDA support compiled in -- a package-selection issue, not a driver problem.",
 [("nvidia-smi","Driver Version: 555.xx  CUDA Version: 12.5 (GPU healthy)",""),
  ("python -c \"import torch; print(torch.__version__)\"","2.3.1+cpu","")],
 "Reinstall PyTorch with the CUDA build matching your driver's supported CUDA version ('pip install torch --index-url https://download.pytorch.org/whl/cu121'); verify with torch.cuda.is_available() afterward."),
("aidev","cuDNN version mismatch crashes training -- 'Loaded runtime CuDNN library: 8.x but source was compiled with 9.x'",
 "The framework build expects a newer cuDNN than the one first on PATH; an old CUDA toolkit install earlier in PATH shadows the correct DLLs, so the mismatched library loads at runtime.",
 [("where cudnn64_8.dll","C:\\Program Files\\NVIDIA GPU Computing Toolkit\\CUDA\\v11.8\\bin\\cudnn64_8.dll (old toolkit first in PATH)","")],
 "Reorder PATH so the toolkit version matching the framework comes first (or remove the stale toolkit), or use conda-managed cudatoolkit/cudnn packages that keep the pair consistent inside the environment."),
("aidev","pip install fails with 'SSL: CERTIFICATE_VERIFY_FAILED' on a corporate machine",
 "The corporate TLS-inspecting proxy re-signs PyPI traffic with an internal CA that Python's bundled certificate store doesn't trust -- pip correctly refuses the intercepted connection.",
 [("python -c \"import certifi; print(certifi.where())\"","...\\certifi\\cacert.pem (lacks the corporate root CA)","")],
 "Add the corporate root CA to pip's trust ('pip config set global.cert C:\\corp\\corp-root.pem' or set REQUESTS_CA_BUNDLE); avoid --trusted-host, which disables verification instead of fixing trust."),
("aidev","A local LLM model download keeps failing partway and restarts from zero each time",
 "The download tool writes to a temp file and discards partial progress on connection resets; the corporate proxy kills long idle connections, so multi-GB downloads never complete in one unbroken session.",
 [("Get-ChildItem \"$env:USERPROFILE\\.cache\\huggingface\" -Recurse -Filter '*.incomplete' | Measure-Object Length -Sum","Sum : 9.2 GB of accumulated .incomplete fragments","")],
 "Use a resume-capable path ('huggingface-cli download' resumes .incomplete files automatically; for direct URLs use curl -C -), clear old fragments, and ask networking to raise idle-timeout for the artifact-hosting domains."),
("aidev","Hugging Face cache corruption -- model loads fail with unexpected EOF/JSON errors after a disk-full incident",
 "The cache holds truncated files from writes that failed when the disk filled; the loaders parse those partial files and fail with misleading format errors rather than re-downloading automatically.",
 [("Get-PSDrive C | Select-Object Free","Free : 2 GB (disk-full incident confirmed in this window)","")],
 "Delete the affected model's cache folder under ~/.cache/huggingface/hub (or run 'huggingface-cli scan-cache' / 'delete-cache' to prune), free adequate space, and re-download; loaders verify sizes on fresh downloads."),
("aidev","PostgreSQL service won't start after an unclean shutdown -- 'could not locate a valid checkpoint record'",
 "The WAL (write-ahead log) is damaged at the point recovery needs, so crash recovery can't find its checkpoint; the service exits during startup recovery rather than running with inconsistent data.",
 [("Get-Content 'C:\\Program Files\\PostgreSQL\\16\\data\\log\\postgresql-*.log' -Tail 5","FATAL: could not locate a valid checkpoint record","")],
 "Restore from backup if available (safest). Otherwise 'pg_resetwal' can force startup but risks losing recent transactions -- take a file-level copy of the data directory first and treat resetwal as last resort."),
("aidev","MongoDB won't start -- 'Unclean shutdown detected' and repair loop on the data directory",
 "The storage engine's metadata was corrupted in the unclean shutdown; automatic recovery fails, and each restart attempt reruns the same failing recovery rather than repairing.",
 [("Get-Content 'C:\\data\\log\\mongod.log' -Tail 5","WiredTiger error ... connection: fatal WT_PANIC: unable to read metadata","")],
 "Restore from backup/replica if possible; standalone last-resort is 'mongod --repair' against a copied data directory (never the only copy). Add a replica set member or scheduled dumps to avoid single-copy risk going forward."),
("aidev","VS Code Remote-SSH connects but immediately drops with 'The process tried to write to a nonexistent pipe'",
 "The remote host's shell startup script prints output (a banner/echo) on non-interactive sessions, which corrupts the SSH channel VS Code uses for its wire protocol -- the connection dies right after handshake.",
 [("ssh devbox 'echo ok'","Welcome to DevBox!!\nok (extra banner output on non-interactive session)","")],
 "Guard interactive-only output in the remote ~/.bashrc behind a tty check ('[ -t 1 ] || return' at the top, or case $- in *i*) so non-interactive channels stay clean; VS Code connects normally once stdout is silent."),
("aidev","Docker Desktop's WSL integration toggle keeps turning itself off for a distro",
 "The distro's WSL version is 1, and Docker Desktop integration requires WSL2 -- Desktop silently disables the toggle at each restart for any WSL1 distro rather than erroring clearly.",
 [("wsl -l -v","NAME      STATE   VERSION\nUbuntu    Running       1","")],
 "Convert the distro to WSL2 ('wsl --set-version Ubuntu 2', after 'wsl --update'), then re-enable the integration toggle in Docker Desktop settings -- it persists once the distro is WSL2."),
]

with open(JSON_PATH, encoding="utf-8") as f:
    data = json.load(f)
with open(JSONL_PATH, encoding="utf-8") as f:
    jsonl_lines = [l for l in f if l.strip()]

existing_ids = set(d["id"] for d in data)
existing_goals = set(d["goal"] for d in data)
n = 1
def next_id():
    global n
    while True:
        cand = f"new-win-repair-{n:03d}"
        n += 1
        if cand not in existing_ids:
            existing_ids.add(cand)
            return cand

skipped = []
base_time = datetime(2026, 7, 31, 9, 0, 0)
i = 0
for domain, goal, summary, commands, recommendation in NEW:
    if goal in existing_goals:
        skipped.append(goal)
        continue
    created = base_time + timedelta(minutes=4 * i)
    i += 1
    steps = [{"command": c, "blocked": False, "exitCode": 0, "stdout": o, "stderr": e, "reason": None} for c, o, e in commands]
    entry = {
        "id": next_id(),
        "createdAt": created.strftime("%Y-%m-%dT%H:%M:%S.000Z"),
        "goal": goal,
        "domain": domain,
        "plan": [f"Diagnose the {domain} issue with read-only checks", "Identify the specific root cause", "Apply the appropriate fix or escalation"],
        "steps": steps,
        "resolved": True,
        "summary": summary,
        "recommendation": recommendation,
        "feedback": {"worked": True, "note": "", "at": (created + timedelta(minutes=2)).strftime("%Y-%m-%dT%H:%M:%S.000Z")}
    }
    data.append(entry)
    existing_goals.add(goal)

    cmd_lines = "\n".join(f"- {c[0]}" for c in commands)
    assistant_content = f"{summary}\nCommands used:\n{cmd_lines}\nRecommendation: {recommendation}"
    chat = {"messages": [
        {"role": "system", "content": f"You are a Windows repair expert specializing in {domain} problems. Diagnose with read-only commands first, then apply safe fixes."},
        {"role": "user", "content": goal},
        {"role": "assistant", "content": assistant_content}
    ]}
    jsonl_lines.append(json.dumps(chat, ensure_ascii=False) + "\n")

with open(JSON_PATH, "w", encoding="utf-8") as f:
    json.dump(data, f, indent=2, ensure_ascii=False)
    f.write("\n")
with open(JSONL_PATH, "w", encoding="utf-8") as f:
    f.writelines(jsonl_lines)

print("Added:", i, "Skipped:", skipped)
print("Total JSON entries:", len(data))
print("Total JSONL lines:", len(jsonl_lines))

ids = [d["id"] for d in data]
assert len(ids) == len(set(ids))
goals = [d["goal"] for d in data]
assert len(goals) == len(set(goals))
with open(JSONL_PATH, encoding="utf-8") as f:
    ulines = [json.loads(l) for l in f if l.strip()]
users = [o["messages"][1]["content"] for o in ulines]
assert len(users) == len(set(users))
assert set(users) == set(goals)
print("All validation passed: no duplicates, files fully mirrored")
